//--------------------------------------------------------------------------//

void dei_ss_door_close( void ) {
	
	if( get_zone_bypass_status() ) return ; 
    
  if( !get_ss_valet() && get_ss_door_bypass() && get_ss_arm() )	{
		set_ss_door_bypass( FALSE );	
 
		if( get_ss_hood_bypass() || get_ss_trunk_bypass() ) {            
			dei_led_flash( DEI_SS_LED_ZONE_BYPASS , LED_ENABLE);								
      }
    else {
      dei_led_flash( DEI_LED_ARM , LED_ENABLE); 
      }						   	
    }    
}

//--------------------------------------------------------------------------//

void dei_ss_door_open( void )
{
	if( get_zone_bypass_status() ) return ; 
	
  //if( ss.armed     && !ss.valet       )
    if( get_ss_arm() && !get_ss_valet() 
			  && !dei_ss_door_is_skip)
	{
		dei_ss_trigger_start( DEI_SS_TRIGGER_ZONE_DOOR ) ;
	}    
}	

//--------------------------------------------------------------------------//
void dei_ss_door_skip_set(void)
{
	dei_ss_door_is_skip = TRUE;
	vrtc_stop(dei_ss_door_skip_vrtc_timer);
	vrtc_update(dei_ss_door_skip_vrtc_timer, DEI_SS_DOOR_SKIP_TIMEOUT);
	vrtc_start(dei_ss_door_skip_vrtc_timer);
}

//--------------------------------------------------------------------------//
void dei_ss_door_skip_clr(void)
{
	dei_ss_door_is_skip = FALSE;
	vrtc_stop(dei_ss_door_skip_vrtc_timer);
}

//--------------------------------------------------------------------------//
void dei_ss_door_skip_timeout_handler(void)
{
	dei_ss_door_is_skip = FALSE;
}

